using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

// Provided infrastructure — do not modify.
public static class CjFlaky
{
    // Completes after delayMs. Keys starting with "slow" simulate a
    // hung backend (5 s) regardless of delayMs.
    public static async Task<string> FetchAsync(string key, int delayMs, CancellationToken ct)
    {
        int wait = key.StartsWith("slow", StringComparison.Ordinal) ? 5000 : delayMs;
        await Task.Delay(wait, ct);
        return "payload:" + key;
    }
}

